// Offline copy of the ERJ form. Generated by make_site.py; cache name changes with the page.
const CACHE = 'erj-form-f2f226f3ad37';
const BUILD = 'f2f226f3ad37';
const FILES = ["./", "./index.html", "./manifest.webmanifest", "./icon-180.png", "./icon-192.png", "./icon-512.png"];

// 'reload' skips the browser's HTTP cache (GitHub Pages lets it keep files for 10 minutes).
// Right after a publish GitHub's servers can still hand out the old page for a minute, so
// the install only goes ahead if the page it fetched carries this build's id; otherwise it
// fails, the current version stays, and the browser tries again on a later visit.
self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const reqs = FILES.map((url) => new Request(url, { cache: 'reload' }));
    const resps = await Promise.all(reqs.map((r) => fetch(r)));
    if (resps.some((r) => !r.ok)) throw new Error('download failed');
    for (const i of [FILES.indexOf('./'), FILES.indexOf('./index.html')]) {
      if (!(await resps[i].clone().text()).includes(BUILD)) throw new Error('stale page');
    }
    const cache = await caches.open(CACHE);
    await Promise.all(resps.map((r, i) => cache.put(reqs[i], r)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('erj-form-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Cache first: the form must open in flight with no connection. A new version arrives as
// a new sw.js, which the browser checks for whenever the app is opened online.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  const key = req.mode === 'navigate' ? './index.html' : req;
  event.respondWith(caches.match(key, { ignoreSearch: true }).then((hit) => hit || fetch(req)));
});
